UPDATE room_types SET code=#{code},name=#{name},description=#{description},max_adults=#{maxAdults},
  max_children=#{maxChildren},max_occupancy=#{maxOccupancy},bed_config=#{bedConfig}::jsonb,amenities=#{amenities}::jsonb,
  images=#{images}::jsonb,room_size_sqm=#{roomSizeSqm},total_units=#{totalUnits},status=#{status},
  disabled_reason=#{disabledReason},data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE id=#{id} AND data_version=#{dataVersion}

UPDATE rate_plans SET code=#{code},name=#{name},currency=#{currency},base_price=#{basePrice},meal_plan=#{mealPlan},
  cancellation_policy=#{cancellationPolicy}::jsonb,occupancy_pricing=#{occupancyPricing}::jsonb,min_stay=#{minStay},
  max_stay=#{maxStay},status=#{status},data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE id=#{id} AND data_version=#{dataVersion}

mapper.select:
SELECT i.*, (total_units-reserved_units-sold_units-blocked_units) AS available_units
FROM room_inventory_daily i WHERE room_type_id=#{roomTypeId}
  AND inventory_date BETWEEN #{startDate} AND #{endDate} ORDER BY inventory_date

mapper.update:
UPDATE room_inventory_daily SET reserved_units=reserved_units+#{quantity},data_version=data_version+1,
  updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND stop_sell=false AND reserved_units+sold_units+blocked_units+#{quantity}<=total_units

UPDATE room_inventory_daily SET reserved_units=reserved_units-#{quantity},sold_units=sold_units+#{quantity},
  data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND reserved_units>=#{quantity}

UPDATE room_inventory_daily SET
  reserved_units=reserved_units-CASE WHEN #{fromReserved} THEN #{quantity} ELSE 0 END,
  sold_units=sold_units-CASE WHEN #{fromReserved} THEN 0 ELSE #{quantity} END,
  data_version=data_version+1,updated_by=#{updatedBy},updated_at=#{updatedAt}
WHERE room_type_id=#{roomTypeId} AND inventory_date >=#{checkIn} AND inventory_date <#{checkOut}
  AND ((#{fromReserved} AND reserved_units>=#{quantity}) OR (NOT #{fromReserved} AND sold_units>=#{quantity}))

