UPDATE hotel_bookings SET booking_status=#{bookingStatus},payment_status=COALESCE(#{paymentStatus},payment_status),
  cancellation_reason=#{cancellationReason},cancelled_at=#{cancelledAt},data_version=data_version+1,
  updated_by=#{updatedBy},updated_at=#{updatedAt} WHERE id=#{id} AND data_version=#{expectedVersion}
